.tbDatasource-title {
    font-size: 1.200rem;
    font-weight: 500;
    padding-bottom: 10px;
}

.tbDatasource-table {
    width: 100%;
    box-shadow: 0 0 10px #ccc;
    border-collapse: collapse;
    white-space: nowrap;
    font-size: 1.000rem;
    color: #757575;
}

.tbDatasource-table td {
    position: relative;
    border-top: 1px solid rgba(0, 0, 0, 0.12);
    border-bottom: 1px solid rgba(0, 0, 0, 0.12);
    padding: 0px 18px;
    box-sizing: border-box;
}

descriptor.controllerScript:
self.onInit = function () {
  const s = self.ctx.$scope;

  // Init values
  s.cpu_usage = '0.00';
  s.cpu_usage_ts = '';
  s.device_temperature = '0.00';
  s.device_temperature_ts = '';
  s.ram_used = 0;
  s.ram_total = 0;
  s.flash_used = 0;
  s.flash_total = 0;
  s.network_type = 'N/A';
  s.modem = 'N/A';
  s.is_online = true;

  // Tailwind (slim)
  if (!document.getElementById('tailwindcss')) {
    window.tailwind = {
      config: {
        safelist: [
          'bg-gray-200', 'bg-green-500', 'bg-red-500', 'bg-orange-500',
          'text-xs', 'text-sm', 'text-gray-500', 'text-green-300',
          'font-mono', 'font-bold', 'font-semibold',
          'rounded', 'rounded-br', 'shadow', 'w-full', 'h-2',
          'transition-all', 'duration-300', 'ease-out',
          'p-2', 'p-4', 'mt-1', 'mt-2', 'mx-auto',
          'absolute', 'top-0', 'left-0', 'space-y-6', 'space-y-3',
          'max-w-md', 'bg-white', 'bg-opacity-80', 'text-white',
          'inline-block', 'px-2', 'py-1'
        ],
        corePlugins: {
          preflight: false
        }
      }
    };
    const script = document.createElement('script');
    script.src = 'https://cdn.tailwindcss.com';
    script.id = 'tailwindcss';
    script.onload = () => {
      console.log('🎯 Tailwind ready');
      setTimeout(() => self.ctx.detectChanges(), 50);
    };
    document.head.appendChild(script);
  } else {
    setTimeout(() => self.ctx.detectChanges(), 50);
  }
};

self.onDataUpdated = function () {
  const s = self.ctx.$scope;
  const data = self.ctx.data;

  const getValue = (key) => {
    const entry = data.find(d => d.dataKey.name === key);
    if (entry?.data?.length) return entry.data.at(-1)[1];
    return null;
  };

  const getTS = (key) => {
    const entry = data.find(d => d.dataKey.name === key);
    if (entry?.data?.length) return new Date(entry.data.at(-1)[0]).toLocaleTimeString();
    return '';
  };

  // CPU & Temp
  const cpuRaw = getValue('cpu_usage');
  s.cpu_usage = cpuRaw ? (parseFloat(cpuRaw) * 100).toFixed(2) : '0.00';
  s.cpu_usage_ts = getTS('cpu_usage');

  const tempRaw = getValue('device_temperature');
  s.device_temperature = tempRaw ? parseFloat(tempRaw).toFixed(2) : '0.00';
  s.device_temperature_ts = getTS('device_temperature');

  // RAM
  s.ram_used = parseFloat(getValue('ram_used') || 0);
  s.ram_total = parseFloat(getValue('ram_total') || 1);

  // Flash
  s.flash_used = parseFloat(getValue('flash_used') || 0);
  s.flash_total = parseFloat(getValue('flash_total') || 1);

  // Modem & Network
  s.network_type = getValue('network_type') || 'Unknown';
  s.modem = getValue('modem') || 'Unknown';

  // Online status
  s.is_online = getValue('is_online') === true || getValue('is_online') === 'true';

  self.ctx.detectChanges();
};

self.onDestroy = function () {
  console.log('🧹 Widget destroyed');
};

